8	import type { CommandModule } from 'yargs';
9	import { type MergedSettings, loadSettings } from '../../config/settings.js';
10	import type { MCPServerConfig } from '@google/gemini-cli-core';
11	import {
12	  MCPServerStatus,
13	  createTransport,
14	  debugLogger,
15	  applyAdminAllowlist,
16	  getAdminBlockedMcpServersMessage,
17	} from '@google/gemini-cli-core';
18	import { Client } from '@modelcontextprotocol/sdk/client/index.js';
19	import { ExtensionManager } from '../../config/extension-manager.js';
20	import { requestConsentNonInteractive } from '../../config/extensions/consent.js';
21	import { promptForSetting } from '../../config/extensions/extensionSettings.js';
22	import { exitCli } from '../utils.js';
23	import chalk from 'chalk';
