25	export async function getMcpServersFromConfig(
26	  settings?: MergedSettings,
27	): Promise<{
28	  mcpServers: Record<string, MCPServerConfig>;
29	  blockedServerNames: string[];
30	}> {
31	  if (!settings) {
32	    settings = loadSettings().merged;
33	  }
34	
35	  const extensionManager = new ExtensionManager({
36	    settings,
37	    workspaceDir: process.cwd(),
38	    requestConsent: requestConsentNonInteractive,
39	    requestSetting: promptForSetting,
40	  });
41	  const extensions = await extensionManager.loadExtensions();
42	  const mcpServers = { ...settings.mcpServers };
43	  for (const extension of extensions) {
44	    Object.entries(extension.mcpServers || {}).forEach(([key, server]) => {
45	      if (mcpServers[key]) {
46	        return;
47	      }
48	      mcpServers[key] = {
49	        ...server,
50	        extension,
51	      };
52	    });
53	  }
54	
55	  const adminAllowlist = settings.admin?.mcp?.config;
56	  const filteredResult = applyAdminAllowlist(mcpServers, adminAllowlist);
57	
58	  return filteredResult;
59	}
