61	async function testMCPConnection(
62	  serverName: string,
63	  config: MCPServerConfig,
64	): Promise<MCPServerStatus> {
65	  const settings = loadSettings();
66	
67	  // SECURITY: Only test connection if workspace is trusted or if it's a remote server.
68	  // stdio servers execute local commands and must never run in untrusted workspaces.
69	  const isStdio = !!config.command;
70	  if (isStdio && !settings.isTrusted) {
71	    return MCPServerStatus.DISCONNECTED;
72	  }
73	
74	  const client = new Client({
75	    name: 'mcp-test-client',
76	    version: '0.0.1',
77	  });
78	
79	  const mcpContext = {
80	    sanitizationConfig: {
81	      enableEnvironmentVariableRedaction: true,
82	      allowedEnvironmentVariables: [],
83	      blockedEnvironmentVariables: settings.merged.advanced.excludedEnvVars,
84	    },
85	    emitMcpDiagnostic: (
86	      severity: 'info' | 'warning' | 'error',
87	      message: string,
88	      error?: unknown,
89	      serverName?: string,
90	    ) => {
91	      // In non-interactive list, we log everything through debugLogger for consistency
92	      if (severity === 'error') {
93	        debugLogger.error(
94	          chalk.red(`Error${serverName ? ` (${serverName})` : ''}: ${message}`),
95	          error,
96	        );
97	      } else if (severity === 'warning') {
98	        debugLogger.warn(
99	          chalk.yellow(
100	            `Warning${serverName ? ` (${serverName})` : ''}: ${message}`,
101	          ),
102	          error,
103	        );
104	      } else {
105	        debugLogger.log(message, error);
106	      }
107	    },
108	    isTrustedFolder: () => settings.isTrusted,
109	  };
110	
111	  let transport;
112	  try {
113	    // Use the same transport creation logic as core
114	    transport = await createTransport(serverName, config, false, mcpContext);
115	  } catch (_error) {
116	    await client.close();
117	    return MCPServerStatus.DISCONNECTED;
118	  }
119	
120	  try {
121	    // Attempt actual MCP connection with short timeout
122	    await client.connect(transport, { timeout: 5000 }); // 5s timeout
123	
124	    // Test basic MCP protocol by pinging the server
125	    await client.ping();
126	
127	    await client.close();
128	    return MCPServerStatus.CONNECTED;
129	  } catch (_error) {
130	    await transport.close();
131	    return MCPServerStatus.DISCONNECTED;
132	  }
133	}
134	
135	async function getServerStatus(
136	  serverName: string,
137	  server: MCPServerConfig,
138	): Promise<MCPServerStatus> {
139	  // Test all server types by attempting actual connection
140	  return testMCPConnection(serverName, server);
141	}
