143	export async function listMcpServers(settings?: MergedSettings): Promise<void> {
144	  const { mcpServers, blockedServerNames } =
145	    await getMcpServersFromConfig(settings);
146	  const serverNames = Object.keys(mcpServers);
147	
148	  if (blockedServerNames.length > 0) {
149	    const message = getAdminBlockedMcpServersMessage(
150	      blockedServerNames,
151	      undefined,
152	    );
153	    debugLogger.log(chalk.yellow(message + '\n'));
154	  }
155	
156	  if (serverNames.length === 0) {
157	    if (blockedServerNames.length === 0) {
158	      debugLogger.log('No MCP servers configured.');
159	    }
160	    return;
161	  }
162	
163	  debugLogger.log('Configured MCP servers:\n');
164	
165	  for (const serverName of serverNames) {
166	    const server = mcpServers[serverName];
167	
168	    const status = await getServerStatus(serverName, server);
169	
170	    let statusIndicator = '';
171	    let statusText = '';
172	    switch (status) {
173	      case MCPServerStatus.CONNECTED:
174	        statusIndicator = chalk.green('✓');
175	        statusText = 'Connected';
176	        break;
177	      case MCPServerStatus.CONNECTING:
178	        statusIndicator = chalk.yellow('…');
179	        statusText = 'Connecting';
180	        break;
181	      case MCPServerStatus.DISCONNECTED:
182	      default:
183	        statusIndicator = chalk.red('✗');
184	        statusText = 'Disconnected';
185	        break;
186	    }
187	
188	    let serverInfo =
189	      serverName +
190	      (server.extension?.name ? ` (from ${server.extension.name})` : '') +
191	      ': ';
192	    if (server.httpUrl) {
193	      serverInfo += `${server.httpUrl} (http)`;
194	    } else if (server.url) {
195	      const type = server.type || 'http';
196	      serverInfo += `${server.url} (${type})`;
197	    } else if (server.command) {
198	      serverInfo += `${server.command} ${server.args?.join(' ') || ''} (stdio)`;
199	    }
200	
201	    debugLogger.log(`${statusIndicator} ${serverInfo} - ${statusText}`);
202	  }
203	}
204	
205	interface ListArgs {
206	  settings?: MergedSettings;
207	}
208	
209	export const listCommand: CommandModule<object, ListArgs> = {
210	  command: 'list',
211	  describe: 'List all configured MCP servers',
212	  handler: async (argv) => {
213	    await listMcpServers(argv.settings);
214	    await exitCli();
215	  },
216	};
