95	/**
96	 * Enum representing the connection status of an MCP server
97	 */
98	export enum MCPServerStatus {
99	  /** Server is disconnected or experiencing errors */
100	  DISCONNECTED = 'disconnected',
101	  /** Server is actively disconnecting */
102	  DISCONNECTING = 'disconnecting',
103	  /** Server is in the process of connecting */
104	  CONNECTING = 'connecting',
105	  /** Server is connected and ready to use */
106	  CONNECTED = 'connected',
107	}
108	
109	/**
110	 * Enum representing the overall MCP discovery state
111	 */
112	export enum MCPDiscoveryState {
113	  /** Discovery has not started yet */
114	  NOT_STARTED = 'not_started',
115	  /** Discovery is currently in progress */
116	  IN_PROGRESS = 'in_progress',
117	  /** Discovery has completed (with or without errors) */
118	  COMPLETED = 'completed',
119	}
