129	/**
130	 * A client for a single MCP server.
131	 *
132	 * This class is responsible for connecting to, discovering tools from, and
133	 * managing the state of a single MCP server.
134	 */
135	export class McpClient implements McpProgressReporter {
136	  private client: Client | undefined;
137	  private transport: Transport | undefined;
138	  private status: MCPServerStatus = MCPServerStatus.DISCONNECTED;
139	  private isRefreshingTools: boolean = false;
140	  private pendingToolRefresh: boolean = false;
141	  private isRefreshingResources: boolean = false;
142	  private pendingResourceRefresh: boolean = false;
143	  private isRefreshingPrompts: boolean = false;
144	  private pendingPromptRefresh: boolean = false;
145	
146	  /**
147	   * Map of progress tokens to tool call IDs.
148	   * This allows us to route progress notifications to the correct tool call.
149	   */
150	  private readonly progressTokenToCallId = new Map<string | number, string>();
151	
152	  constructor(
153	    private readonly serverName: string,
154	    private readonly serverConfig: MCPServerConfig,
155	    private readonly toolRegistry: ToolRegistry,
156	    private readonly promptRegistry: PromptRegistry,
157	    private readonly resourceRegistry: ResourceRegistry,
158	    private readonly workspaceContext: WorkspaceContext,
159	    private readonly cliConfig: McpContext,
160	    private readonly debugMode: boolean,
161	    private readonly clientVersion: string,
162	    private readonly onContextUpdated?: (signal?: AbortSignal) => Promise<void>,
163	  ) {}
164	
165	  /**
166	   * Connects to the MCP server.
167	   */
168	  async connect(): Promise<void> {
169	    if (this.status !== MCPServerStatus.DISCONNECTED) {
170	      throw new Error(
171	        `Can only connect when the client is disconnected, current state is ${this.status}`,
172	      );
173	    }
174	    this.updateStatus(MCPServerStatus.CONNECTING);
175	    try {
176	      this.client = await connectToMcpServer(
177	        this.clientVersion,
178	        this.serverName,
179	        this.serverConfig,
180	        this.debugMode,
181	        this.workspaceContext,
182	        this.cliConfig,
183	      );
184	
185	      this.registerNotificationHandlers();
186	
187	      const originalOnError = this.client.onerror;
188	      this.client.onerror = (error) => {
189	        if (this.status !== MCPServerStatus.CONNECTED) {
190	          return;
191	        }
192	        if (originalOnError) originalOnError(error);
193	        this.cliConfig.emitMcpDiagnostic(
194	          'error',
195	          `MCP ERROR (${this.serverName})`,
196	          error,
197	          this.serverName,
198	        );
199	        this.updateStatus(MCPServerStatus.DISCONNECTED);
200	      };
201	      this.updateStatus(MCPServerStatus.CONNECTED);
202	    } catch (error) {
203	      this.updateStatus(MCPServerStatus.DISCONNECTED);
204	      throw error;
205	    }
206	  }
207	
208	  /**
209	   * Discovers tools and prompts from the MCP server.
210	   */
211	  async discover(cliConfig: McpContext): Promise<void> {
212	    this.assertConnected();
213	
214	    const prompts = await this.fetchPrompts();
215	    const tools = await this.discoverTools(cliConfig);
216	    const resources = await this.discoverResources();
217	    this.updateResourceRegistry(resources);
218	
219	    if (prompts.length === 0 && tools.length === 0 && resources.length === 0) {
220	      throw new Error('No prompts, tools, or resources found on the server.');
221	    }
222	
