63	 * Handles case-insensitive matching and plain name fallback for ext: servers.
64	 */
65	export function isInSettingsList(
66	  serverId: string,
67	  list: string[],
68	): { found: boolean; deprecationWarning?: string } {
69	  const normalizedId = normalizeServerId(serverId);
70	  const normalizedList = list.map(normalizeServerId);
71	
72	  // Exact canonical match
73	  if (normalizedList.includes(normalizedId)) {
74	    return { found: true };
75	  }
76	
77	  // Backward compat: for ext: servers, check if plain name matches
78	  if (normalizedId.startsWith('ext:')) {
79	    const plainName = normalizedId.split(':').pop();
80	    if (plainName && normalizedList.includes(plainName)) {
81	      return {
82	        found: true,
83	        deprecationWarning:
84	          `Settings reference '${plainName}' matches extension server '${serverId}'. ` +
85	          `Update your settings to use the full identifier '${serverId}' instead.`,
86	      };
87	    }
88	  }
89	
90	  return { found: false };
91	}
