157	  // 4. Session disable check (before file-based enablement)
158	  if (config.enablement?.isSessionDisabled(normalizedId)) {
159	    return {
160	      allowed: false,
161	      reason: `Server '${serverId}' is disabled for this session. Run 'gemini mcp enable ${serverId} --session' to clear.`,
162	      blockType: 'session',
