171	    return {
172	      allowed: false,
173	      reason: `Server '${serverId}' is disabled. Run 'gemini mcp enable ${serverId}' to enable.`,
174	      blockType: 'enablement',
175	    };
176	  }
177	
178	  return { allowed: true };
